"""
FireRedVAD speech islands for VAD-owned timing (optional alternative to TEN).

Upstream: FireRedTeam/FireRedVAD (Apache-2.0). Segment length is capped at
JAV-friendly values (~5–7s) via ``max_speech_frame`` (10 ms frames).
"""

from __future__ import annotations

import logging
import shutil
import tempfile
import threading
from pathlib import Path
from typing import Any

import numpy as np

_log = logging.getLogger("transub_engine.vad.firered_vad_seg")

SAMPLE_RATE = 16000
# Upstream comment: max_speech_frame=2000 → 20s → 10 ms/frame.
_FRAME_MS = 10.0
# WhisperJAV-style JAV caps: 5–7s (default 6s = 600 frames).
_DEFAULT_MAX_SPEECH_S = 6.0
_DEFAULT_THRESHOLD = 0.40
_DEFAULT_MIN_SPEECH_S = 0.20
_DEFAULT_MIN_SILENCE_S = 0.20
# Soft-AV / anime-whisper FireRed: keep islands short enough that mix audio
# (no Demucs) still yields 1–2 phrases per ASR call. 5s floors glued
# 「キンピラ…作ってみた」into one blob and broke paint (TV_LATE).
_MAX_SPEECH_S_LO = 3.5
_MAX_SPEECH_S_HI = 7.5

_MODEL_CACHE: dict[str, Any] = {}
_MODEL_LOCK = threading.Lock()


def clear_firered_vad_cache() -> None:
    """Drop cached FireRedVAD models and free ROCm/CUDA scratch.

    Anime-whisper loads CTranslate2 after FireRed; keeping a HIP model live
    next to CT2/OpenMP often trips OMP Error #15 on Windows ROCm.
    """
    with _MODEL_LOCK:
        _MODEL_CACHE.clear()
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch

        if bool(getattr(torch, "cuda", None) and torch.cuda.is_available()):
            try:
                torch.cuda.synchronize()
            except Exception:
                pass
            try:
                torch.cuda.empty_cache()
            except Exception:
                pass
    except Exception:
        pass


def firered_vad_available() -> bool:
    try:
        from fireredvad import FireRedVad  # noqa: F401

        return True
    except Exception:
        return False


def firered_weights_dir() -> Path | None:
    """Return local VAD weight directory when catalog model is installed."""
    try:
        from ..download import is_model_installed, model_local_path

        if not is_model_installed("firered-vad"):
            return None
        root = model_local_path("firered-vad")
    except Exception:
        return None
    nested = root / "VAD"
    if (nested / "model.pth.tar").is_file() and (nested / "cmvn.ark").is_file():
        return nested
    if (root / "model.pth.tar").is_file() and (root / "cmvn.ark").is_file():
        return root
    return None


def _seconds_to_frames(seconds: float) -> int:
    return max(1, int(round(float(seconds) * 1000.0 / _FRAME_MS)))


def _threshold_from_vad_options(vad_options: dict[str, Any] | None) -> float:
    """Map Transub VAD threshold / sensitive flag onto FireRed speech_threshold."""
    opts = vad_options if isinstance(vad_options, dict) else {}
    raw = opts.get("threshold", opts.get("vadThreshold", None))
    try:
        if raw is not None and str(raw).strip() != "":
            t = float(raw)
            if 0.0 < t < 1.0:
                # Honor UI threshold in a FireRed-safe band. Soft-AV mix (no Demucs)
                # needs ~0.22–0.30; remapping everything ≤0.25 up to 0.32 used to
                # erase preset tuning and glue soft dialogue islands together.
                if t >= 0.55:
                    return 0.50
                return max(0.18, min(0.55, t))
    except (TypeError, ValueError):
        pass
    if opts.get("sensitive") or opts.get("vadSensitive"):
        return 0.28
    return _DEFAULT_THRESHOLD


def resolve_firered_params(
    vad_options: dict[str, Any] | None = None,
    *,
    threshold: float | None = None,
    max_speech_s: float | None = None,
    min_speech_s: float | None = None,
    min_silence_s: float | None = None,
    merge_gap_s: float | None = None,
    pad_s: float | None = None,
) -> dict[str, float]:
    """Resolve FireRed collect knobs from job VAD options + explicit overrides."""
    opts = vad_options if isinstance(vad_options, dict) else {}

    th = float(threshold) if threshold is not None else _threshold_from_vad_options(opts)

    if max_speech_s is not None:
        max_s = float(max_speech_s)
    else:
        max_ms = opts.get("maxSingleSegmentMs", opts.get("max_single_segment_time"))
        try:
            max_s = float(max_ms) / 1000.0 if max_ms is not None else _DEFAULT_MAX_SPEECH_S
        except (TypeError, ValueError):
            max_s = _DEFAULT_MAX_SPEECH_S
    max_s = max(_MAX_SPEECH_S_LO, min(_MAX_SPEECH_S_HI, max_s))

    if min_speech_s is not None:
        min_sp = float(min_speech_s)
    else:
        ms = opts.get("minSpeechMs", opts.get("min_speech_duration_ms"))
        try:
            min_sp = float(ms) / 1000.0 if ms is not None else _DEFAULT_MIN_SPEECH_S
        except (TypeError, ValueError):
            min_sp = _DEFAULT_MIN_SPEECH_S
    min_sp = max(0.05, min(2.0, min_sp))

    if min_silence_s is not None:
        min_sil = float(min_silence_s)
    else:
        ms = opts.get("minSilenceMs", opts.get("min_silence_duration_ms"))
        try:
            min_sil = float(ms) / 1000.0 if ms is not None else _DEFAULT_MIN_SILENCE_S
        except (TypeError, ValueError):
            min_sil = _DEFAULT_MIN_SILENCE_S
    min_sil = max(0.05, min(2.0, min_sil))

    if pad_s is not None:
        pad = float(pad_s)
    else:
        ms = opts.get("speechPadMs", opts.get("speech_pad_ms"))
        try:
            pad = float(ms) / 1000.0 if ms is not None else 0.08
        except (TypeError, ValueError):
            pad = 0.08
    pad = max(0.0, min(0.5, pad))

    if merge_gap_s is not None:
        gap = float(merge_gap_s)
    else:
        # Prefer explicit silence length as merge gap (soft AV: ~0.3s).
        gap = min_sil
    gap = max(0.05, min(1.5, gap))

    return {
        "threshold": th,
        "max_speech_s": max_s,
        "min_speech_s": min_sp,
        "min_silence_s": min_sil,
        "merge_gap_s": gap,
        "pad_s": pad,
        "extend_speech_s": min(0.25, pad * 0.5),
    }


def _get_vad(
    model_dir: Path,
    *,
    speech_threshold: float,
    max_speech_s: float,
    min_speech_s: float,
    min_silence_s: float,
    use_gpu: bool,
    extend_speech_s: float = 0.0,
) -> Any:
    from fireredvad import FireRedVad, FireRedVadConfig

    max_frames = _seconds_to_frames(max_speech_s)
    min_speech_frames = _seconds_to_frames(min_speech_s)
    min_silence_frames = _seconds_to_frames(min_silence_s)
    extend_frames = _seconds_to_frames(extend_speech_s) if extend_speech_s > 0 else 0
    key = (
        f"{model_dir}|th={speech_threshold:.3f}|max={max_frames}|"
        f"min={min_speech_frames}|sil={min_silence_frames}|ext={extend_frames}|gpu={int(use_gpu)}"
    )
    with _MODEL_LOCK:
        cached = _MODEL_CACHE.get(key)
        if cached is not None:
            return cached
        config = FireRedVadConfig(
            use_gpu=bool(use_gpu),
            smooth_window_size=5,
            speech_threshold=float(speech_threshold),
            min_speech_frame=min_speech_frames,
            max_speech_frame=max_frames,
            min_silence_frame=min_silence_frames,
            merge_silence_frame=0,
            extend_speech_frame=extend_frames,
            chunk_max_frame=30000,
        )
        model = FireRedVad.from_pretrained(str(model_dir), config)
        _MODEL_CACHE[key] = model
        return model


def _write_pcm_f32_mono_16k_wav(audio_f32: np.ndarray, out_wav: Path) -> Path:
    """Write already-decoded mono float32 @ 16 kHz as PCM16 WAV (no second ffmpeg)."""
    import wave

    out_wav.parent.mkdir(parents=True, exist_ok=True)
    pcm = np.asarray(audio_f32, dtype=np.float32).reshape(-1)
    i16 = np.clip(np.rint(pcm * 32767.0), -32768, 32767).astype(np.int16)
    with wave.open(str(out_wav), "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(int(SAMPLE_RATE))
        wf.writeframes(i16.tobytes())
    return out_wav


def _write_mono_16k_wav(media_path: str, out_wav: Path, *, max_media_s: float | None) -> Path:
    """Extract 16 kHz 16-bit mono PCM wav for FireRedVad.detect (ffmpeg fallback)."""
    from ..ffmpeg_util import resolve_ffmpeg
    import subprocess
    import os

    ffmpeg = resolve_ffmpeg()
    if not ffmpeg:
        raise RuntimeError("ffmpeg not found; cannot decode audio for FireRedVAD")
    out_wav.parent.mkdir(parents=True, exist_ok=True)
    cmd = [
        ffmpeg,
        "-hide_banner",
        "-loglevel",
        "error",
        "-y",
        "-i",
        media_path,
    ]
    if max_media_s is not None and float(max_media_s) > 0:
        cmd.extend(["-t", f"{float(max_media_s):.3f}"])
    cmd.extend(
        [
            "-ac",
            "1",
            "-ar",
            str(SAMPLE_RATE),
            "-acodec",
            "pcm_s16le",
            "-f",
            "wav",
            str(out_wav),
        ]
    )
    run_kw: dict[str, Any] = {
        "capture_output": True,
        "check": False,
        "timeout": 600,
    }
    if os.name == "nt":
        run_kw["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    proc = subprocess.run(cmd, **run_kw)
    if proc.returncode != 0 or not out_wav.is_file():
        err = (proc.stderr or b"").decode("utf-8", errors="replace")[:800]
        raise RuntimeError(f"ffmpeg wav extract failed for FireRedVAD: {err}")
    return out_wav


def merge_firered_intervals(
    intervals: list[tuple[float, float]] | None,
    *,
    merge_gap_s: float,
    max_speech_s: float,
    pad_s: float = 0.0,
    min_speech_s: float = 0.0,
    audio_end_s: float | None = None,
) -> list[tuple[float, float]]:
    """
    Merge nearby FireRed stamps, but never glue past ``max_speech_s``.

    Prior merge ignored ``max_speech_s`` and rebuilt 20–40s mega-islands on
    Demucs vocals (hot residual), forcing expensive silence-refine + fat Qwen
    batch pads.
    """
    raw = [
        (float(s), float(e))
        for s, e in (intervals or [])
        if float(e) > float(s)
    ]
    if not raw:
        return []
    gap = max(0.0, float(merge_gap_s))
    max_s = max(0.35, float(max_speech_s))
    pad = max(0.0, float(pad_s))
    min_sp = max(0.0, float(min_speech_s))
    audio_end = float(audio_end_s) if audio_end_s is not None and float(audio_end_s) > 0 else None

    merged: list[list[float]] = []
    for s, e in sorted(raw, key=lambda p: p[0]):
        if merged and s <= merged[-1][1] + gap:
            cand_end = max(merged[-1][1], e)
            if cand_end - merged[-1][0] <= max_s + 0.05:
                merged[-1][1] = cand_end
                continue
        merged.append([s, e])

    # Hard-split any leftover overlong stamp (model occasionally emits >max).
    capped: list[tuple[float, float]] = []
    for s, e in merged:
        cur = float(s)
        end = float(e)
        while end - cur > max_s + 0.08:
            capped.append((cur, cur + max_s))
            cur = cur + max_s
        if end > cur + 0.05:
            capped.append((cur, end))

    out: list[tuple[float, float]] = []
    for s, e in capped:
        s2 = max(0.0, s - pad)
        e2 = (min(audio_end, e + pad) if audio_end is not None else e + pad)
        if e2 - s2 >= min_sp:
            out.append((s2, e2))
    return out


def collect_firered_vad_intervals(
    media_path: str,
    *,
    threshold: float | None = None,
    max_speech_s: float | None = None,
    min_speech_s: float | None = None,
    min_silence_s: float | None = None,
    merge_gap_s: float | None = None,
    pad_s: float | None = None,
    max_media_s: float | None = None,
    vad_options: dict[str, Any] | None = None,
    device: str = "auto",
) -> list[tuple[float, float]]:
    """Run FireRedVAD and return speech ``(start, end)`` intervals in seconds."""
    intervals, _audio = collect_firered_vad_intervals_with_audio(
        media_path,
        threshold=threshold,
        max_speech_s=max_speech_s,
        min_speech_s=min_speech_s,
        min_silence_s=min_silence_s,
        merge_gap_s=merge_gap_s,
        pad_s=pad_s,
        max_media_s=max_media_s,
        vad_options=vad_options,
        device=device,
    )
    return intervals


def collect_firered_vad_intervals_with_audio(
    media_path: str,
    *,
    threshold: float | None = None,
    max_speech_s: float | None = None,
    min_speech_s: float | None = None,
    min_silence_s: float | None = None,
    merge_gap_s: float | None = None,
    pad_s: float | None = None,
    max_media_s: float | None = None,
    vad_options: dict[str, Any] | None = None,
    device: str = "auto",
) -> tuple[list[tuple[float, float]], np.ndarray]:
    """
    Run FireRedVAD; return ``(intervals, audio_f32)``.

    ``audio_f32`` is mono float32 @ 16 kHz (decoded via TEN helper) so island
    ASR callers can slice without a second ffmpeg pass when desired.
    Timing knobs resolve from ``vad_options`` unless explicitly overridden.
    """
    if not firered_vad_available():
        raise RuntimeError(
            "FireRedVAD 未安装。请下载 firered-vad 模型（会安装 fireredvad 依赖）。"
        )
    model_dir = firered_weights_dir()
    if model_dir is None:
        raise RuntimeError(
            "FireRedVAD 权重未安装。请在模型库下载 firered-vad（FireRedTeam/FireRedVAD）。"
        )

    params = resolve_firered_params(
        vad_options,
        threshold=threshold,
        max_speech_s=max_speech_s,
        min_speech_s=min_speech_s,
        min_silence_s=min_silence_s,
        merge_gap_s=merge_gap_s,
        pad_s=pad_s,
    )
    th = float(params["threshold"])
    max_s = float(params["max_speech_s"])
    min_sp = float(params["min_speech_s"])
    min_sil = float(params["min_silence_s"])
    gap = float(params["merge_gap_s"])
    pad = float(params["pad_s"])
    extend_s = float(params["extend_speech_s"])

    use_gpu = False
    d = str(device or "auto").strip().lower()
    if d in ("cuda", "gpu"):
        use_gpu = True
    elif d == "auto":
        try:
            import torch

            use_gpu = bool(torch.cuda.is_available())
        except Exception:
            use_gpu = False

    name = Path(media_path).name
    _log.info(
        "FireRedVAD collect start: %s | threshold=%.2f | max_speech=%.1fs | "
        "min_speech=%.2fs | min_sil=%.2fs | pad=%.2fs | extend=%.2fs | gap=%.2fs | gpu=%s",
        name,
        th,
        max_s,
        min_sp,
        min_sil,
        pad,
        extend_s,
        gap,
        use_gpu,
    )

    # Decode once for island ASR reuse (same clock as TEN), then write WAV from
    # that buffer — avoid a second full-length ffmpeg extract.
    import time

    from .ten_vad_seg import _load_float32_mono_16k

    t0 = time.perf_counter()
    audio_f32 = _load_float32_mono_16k(media_path, max_media_s=max_media_s)
    decode_s = time.perf_counter() - t0
    wav_s = 0.0
    detect_s = 0.0

    work = Path(tempfile.mkdtemp(prefix="firered_vad_"))
    try:
        t1 = time.perf_counter()
        try:
            wav = _write_pcm_f32_mono_16k_wav(audio_f32, work / "audio_16k.wav")
        except Exception as err:
            _log.warning(
                "FireRedVAD wav-from-pcm failed (%s); falling back to ffmpeg",
                err,
            )
            wav = _write_mono_16k_wav(
                media_path,
                work / "audio_16k.wav",
                max_media_s=max_media_s,
            )
        wav_s = time.perf_counter() - t1
        vad = _get_vad(
            model_dir,
            speech_threshold=th,
            max_speech_s=max_s,
            min_speech_s=min_sp,
            min_silence_s=min_sil,
            use_gpu=use_gpu,
            extend_speech_s=extend_s,
        )
        t2 = time.perf_counter()
        result, _probs = vad.detect(str(wav))
        detect_s = time.perf_counter() - t2
    finally:
        shutil.rmtree(work, ignore_errors=True)

    raw_ts = []
    if isinstance(result, dict):
        raw_ts = list(result.get("timestamps") or [])
    intervals: list[tuple[float, float]] = []
    for item in raw_ts:
        try:
            if isinstance(item, (list, tuple)) and len(item) >= 2:
                s, e = float(item[0]), float(item[1])
            else:
                continue
        except (TypeError, ValueError):
            continue
        if e > s:
            intervals.append((s, e))

    audio_end = len(audio_f32) / float(SAMPLE_RATE) if len(audio_f32) else 0.0
    out = merge_firered_intervals(
        intervals,
        merge_gap_s=gap,
        max_speech_s=max_s,
        pad_s=pad,
        min_speech_s=float(min_sp),
        audio_end_s=audio_end,
    )

    spoken = sum(e - s for s, e in out)
    _log.info(
        "FireRedVAD collect done: %s | audio=%.1fs | raw=%d | merged=%d | spoken=%.1fs "
        "(%.0f%%) | first=%s | last=%s | decode=%.2fs wav=%.2fs detect=%.2fs",
        name,
        audio_end,
        len(intervals),
        len(out),
        spoken,
        (100.0 * spoken / audio_end) if audio_end > 0 else 0.0,
        f"{out[0][0]:.1f}-{out[0][1]:.1f}s" if out else "-",
        f"{out[-1][0]:.1f}-{out[-1][1]:.1f}s" if out else "-",
        decode_s,
        wav_s,
        detect_s,
    )
    return out, audio_f32
